fn cancel_target_outcome(
    disposition: CancelOrderStateDispositionV1,
    order: Option<&SimOrderRecordV1>,
) -> Result<
    (CancelTargetOutcomeV1, Option<OrderLifecycleFeedbackSeedV1>),
    SubmissionProcessingErrorV1,
> {
    Ok(match disposition {
        CancelOrderStateDispositionV1::NotFound => (
            CancelTargetOutcomeV1::NotCanceledNoEffect(
                CancelNotCanceledReasonV1::NotFoundOrNotOwned,
            ),
            None,
        ),
        CancelOrderStateDispositionV1::NoCancellableRemainder => (
            CancelTargetOutcomeV1::NotCanceledNoEffect(
                CancelNotCanceledReasonV1::NoCancellableRemainder,
            ),
            None,
        ),
        CancelOrderStateDispositionV1::Canceled(effect) => {
            let order = order.ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "成功撤单缺少原订单证据",
            ))?;
            let account_delta = effect
                .account_delta
                .as_ref()
                .map(|delta| AccountDeltaReferenceV1::from(delta.as_ref()));
            let feedback = effect
                .account_delta
                .map(|account_delta| OrderLifecycleFeedbackSeedV1 {
                    platform_order_id: order.platform_order_id.clone(),
                    condition_id: order.condition_id.clone(),
                    token_id: order.token_id.clone(),
                    event_kind: OrderLifecycleEventKindV1::CallerCanceled,
                    order_status: simulated_order_status("CANCELED"),
                    venue_dust_closed_base_units: 0,
                    venue_dust_released_quote_units: 0,
                    market_resolved_canceled_base_units: 0,
                    market_resolved_released_quote_units: 0,
                    account_delta,
                });
            (
                CancelTargetOutcomeV1::Canceled(CanceledTargetMeasurementV1 {
                    canceled_base_quantity_shares: decimal_from_micro_units_v1(
                        effect
                            .pending_base_units_before
                            .checked_add(effect.open_base_units_before)
                            .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                                "撤单 base 数量溢出",
                            ))?,
                    )?,
                    released_quote_amount_pusd: decimal_from_micro_units_v1(
                        effect.released_open_quote_units,
                    )?,
                    account_delta,
                }),
                feedback,
            )
        }
    })
}

fn allocate_immediate_taker_fee(
    session: &SimSession,
    fills: &mut [SimFillRecordV1],
) -> Result<u128, SubmissionProcessingErrorV1> {
    allocate_immediate_taker_fee_against_rules(session.rule_snapshot(), fills)
}

fn allocate_immediate_taker_fee_against_rules(
    rule_snapshot: &SealedProcessRuleSnapshot,
    fills: &mut [SimFillRecordV1],
) -> Result<u128, SubmissionProcessingErrorV1> {
    let rules = rule_snapshot.synchronized_rules();
    if !rules.fees_enabled || fills.is_empty() {
        return Ok(0);
    }
    let fee_inputs = fills
        .iter()
        .map(|fill| {
            (
                fill.trade_id.as_str(),
                fill.base_units,
                fill.price_pusd_per_share,
            )
        })
        .collect::<Vec<_>>();
    let (total_units, allocations) = allocate_taker_fee_micro_units_v1(
        &fee_inputs,
        rules.fee_schedule.rate.value(),
        rules.fee_schedule.exponent,
    )?;
    for (fill, fee_units) in fills.iter_mut().zip(allocations) {
        fill.immediate_taker_fee_units = fee_units;
    }
    Ok(total_units)
}

fn taker_fill_records(
    platform_order_id: &str,
    condition_id: &str,
    token_id: &str,
    matched_at_utc_ms: i64,
    plan: &QueueMatchPlanV1,
) -> Result<Vec<SimFillRecordV1>, SubmissionProcessingErrorV1> {
    let mut cumulative_base = 0_u128;
    let mut records = Vec::with_capacity(plan.fills.len());
    for fill in &plan.fills {
        let trade_id = stable_fill_id(
            "TAKER",
            platform_order_id,
            &fill.segment_id.0,
            cumulative_base,
        );
        records.push(SimFillRecordV1 {
            trade_id,
            platform_order_id: platform_order_id.to_owned(),
            condition_id: condition_id.to_owned(),
            token_id: token_id.to_owned(),
            matched_at_utc_ms,
            liquidity_role: SimLiquidityRoleV1::Taker,
            source_identity: fill.segment_id.0.clone(),
            maker_depletion_evidence: None,
            price_pusd_per_share: fill.price_pusd_per_share,
            base_units: fill.base_units,
            quote_units: fill.quote_units,
            immediate_taker_fee_units: 0,
            finality_path: None,
            finality_path_ordinal: None,
            finality_state: None,
            economic_application_delta: None,
        });
        cumulative_base = cumulative_base.checked_add(fill.base_units).ok_or(
            SubmissionProcessingErrorV1::InternalInvariant("成交 base 累计溢出"),
        )?;
    }
    Ok(records)
}

enum PreparedSubmissionOrderV2 {
    Rejected(SubmissionRejectedReasonV1),
    Ready(SimOrderRecordV1),
}

#[allow(clippy::too_many_arguments)]
fn submission_order_record_v2(
    prepared: &PreparedSubmissionV1,
    platform_order_id: String,
    item_idempotency_identity: &str,
    kind: SimOrderKindStateV1,
    source_price_pusd_per_share: Decimal,
    accepted_base_units: Option<u128>,
    matched_base_units: u128,
    open_base_units: u128,
    accepted_quote_units: u128,
    matched_quote_units: u128,
    open_quote_units: u128,
    released_quote_units: u128,
    sdk_taker_amount_audit_base_units: Option<u128>,
    terminal_reason: Option<SimOrderTerminalReasonV1>,
) -> SimOrderRecordV1 {
    SimOrderRecordV1 {
        platform_order_id,
        global_request_id: prepared.global_request_id.clone(),
        item_id: prepared.item_id.clone(),
        item_idempotency_identity: item_idempotency_identity.to_owned(),
        condition_id: prepared.condition_id.0.clone(),
        token_id: prepared.token_id.0.clone(),
        created_at_utc_ms: prepared.effective_processing_at_utc_ms,
        last_updated_at_utc_ms: prepared.effective_processing_at_utc_ms,
        kind,
        source_price_pusd_per_share,
        accepted_base_units,
        matched_base_units,
        pending_maker_depletion_base_units: 0,
        pending_maker_depletion_evidence: None,
        open_base_units,
        expired_base_units: 0,
        expired_released_quote_units: 0,
        expired_at_utc_ms: None,
        gtd_expiration_identity: None,
        venue_dust_closed_base_units: 0,
        venue_dust_released_quote_units: 0,
        venue_dust_at_utc_ms: None,
        venue_dust_identity: None,
        market_resolved_canceled_base_units: 0,
        market_resolved_released_quote_units: 0,
        market_resolved_at_utc_ms: None,
        market_resolution_effect_identity: None,
        canceled_base_units: 0,
        canceled_released_quote_units: 0,
        canceled_at_utc_ms: None,
        caller_cancel_effect_identity: None,
        terminalized_pending_maker_depletion_evidence: None,
        accepted_quote_units,
        matched_quote_units,
        open_quote_units,
        released_quote_units,
        sdk_taker_amount_audit_base_units,
        immediate_taker_fee_encumbered_units: 0,
        terminal_reason,
    }
}

fn prepare_submission_order_from_match_v2(
    prepared: &PreparedSubmissionV1,
    platform_order_id: String,
    item_idempotency_identity: &str,
    plan: &QueueMatchPlanV1,
) -> Result<PreparedSubmissionOrderV2, SubmissionProcessingErrorV1> {
    match &prepared.order {
        PreparedBuyOrderV1::GtcLimit {
            limit_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
            ..
        }
        | PreparedBuyOrderV1::GtdLimit {
            limit_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
            ..
        } => {
            let accepted_base_units = micro_units_v1(*taker_amount_shares)?;
            let accepted_quote_units = micro_units_v1(*maker_amount_pusd)?;
            let allocated_quote_units = cumulative_segment_quote_units_v1(
                accepted_base_units,
                accepted_quote_units,
                plan.matched_base_units,
            )?;
            let open_base_units = accepted_base_units
                .checked_sub(plan.matched_base_units)
                .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                    "限价成交 base 超出接受数量",
                ))?;
            let open_quote_units = accepted_quote_units
                .checked_sub(allocated_quote_units)
                .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                    "限价开放 quote 超出接受本金",
                ))?;
            let released_quote_units = allocated_quote_units
                .checked_sub(plan.used_quote_units)
                .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                    "限价价格改善 quote 超出接受本金",
                ))?;
            let kind = match prepared.order {
                PreparedBuyOrderV1::GtcLimit { .. } => SimOrderKindStateV1::Gtc,
                PreparedBuyOrderV1::GtdLimit {
                    expires_at_utc_ms, ..
                } => SimOrderKindStateV1::Gtd { expires_at_utc_ms },
                PreparedBuyOrderV1::FokMarket { .. } | PreparedBuyOrderV1::FakMarket { .. } => {
                    unreachable!("限价分支已匹配")
                }
            };
            Ok(PreparedSubmissionOrderV2::Ready(
                submission_order_record_v2(
                    prepared,
                    platform_order_id,
                    item_idempotency_identity,
                    kind,
                    *limit_price_pusd_per_share,
                    Some(accepted_base_units),
                    plan.matched_base_units,
                    open_base_units,
                    accepted_quote_units,
                    plan.used_quote_units,
                    open_quote_units,
                    released_quote_units,
                    None,
                    None,
                ),
            ))
        }
        PreparedBuyOrderV1::FokMarket {
            worst_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
        }
        | PreparedBuyOrderV1::FakMarket {
            worst_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
        } => {
            let accepted_quote_units = micro_units_v1(*maker_amount_pusd)?;
            let fok = matches!(&prepared.order, PreparedBuyOrderV1::FokMarket { .. });
            if fok && plan.used_quote_units != accepted_quote_units {
                return Ok(PreparedSubmissionOrderV2::Rejected(
                    SubmissionRejectedReasonV1::FokNotFullyFilled,
                ));
            }
            if !fok && plan.fills.is_empty() {
                return Ok(PreparedSubmissionOrderV2::Rejected(
                    SubmissionRejectedReasonV1::FakNoMatch,
                ));
            }
            Ok(PreparedSubmissionOrderV2::Ready(
                submission_order_record_v2(
                    prepared,
                    platform_order_id,
                    item_idempotency_identity,
                    if fok {
                        SimOrderKindStateV1::Fok
                    } else {
                        SimOrderKindStateV1::Fak
                    },
                    *worst_price_pusd_per_share,
                    None,
                    plan.matched_base_units,
                    0,
                    accepted_quote_units,
                    plan.used_quote_units,
                    0,
                    accepted_quote_units
                        .checked_sub(plan.used_quote_units)
                        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                            "市价 BUY 消耗 quote 超出预算",
                        ))?,
                    Some(micro_units_v1(*taker_amount_shares)?),
                    (!fok).then_some(SimOrderTerminalReasonV1::FakCompleted),
                ),
            ))
        }
    }
}

struct PreparedSubmissionExecutionDeltaResultV2 {
    outcome: SubmissionItemOutcomeV1,
    order_feedbacks: Vec<OrderLifecycleFeedbackSeedV1>,
    trade_feedbacks: Vec<TradeFinalityLifecycleEffectsV1>,
    execution_changed: bool,
}

fn prepare_submission_execution_delta_v2<'a>(
    execution: PreparedExecutionDriveDeltaV2<'a>,
    session_spec: &SessionSpecV2,
    rule_snapshot: &SealedProcessRuleSnapshot,
    finality_policy: &TradeFinalityPolicyV1,
    prepared: &PreparedSubmissionV1,
    effect_identity: &str,
    item_idempotency_identity: &str,
) -> Result<
    (
        PreparedExecutionDriveDeltaV2<'a>,
        PreparedSubmissionExecutionDeltaResultV2,
    ),
    SubmissionProcessingErrorV1,
> {
    let platform_order_id = stable_order_id(session_spec, effect_identity);
    let builder = match &prepared.order {
        PreparedBuyOrderV1::GtcLimit {
            limit_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
            ..
        }
        | PreparedBuyOrderV1::GtdLimit {
            limit_price_pusd_per_share,
            maker_amount_pusd,
            taker_amount_shares,
            ..
        } => execution.prepare_new_order_taker_buy_by_base_v2(
            &prepared.condition_id.0,
            &prepared.token_id.0,
            *limit_price_pusd_per_share,
            micro_units_v1(*taker_amount_shares)?,
            micro_units_v1(*maker_amount_pusd)?,
        )?,
        PreparedBuyOrderV1::FokMarket {
            worst_price_pusd_per_share,
            maker_amount_pusd,
            ..
        }
        | PreparedBuyOrderV1::FakMarket {
            worst_price_pusd_per_share,
            maker_amount_pusd,
            ..
        } => execution.prepare_new_order_taker_buy_by_quote_v2(
            &prepared.condition_id.0,
            &prepared.token_id.0,
            *worst_price_pusd_per_share,
            micro_units_v1(*maker_amount_pusd)?,
        )?,
    };
    let plan = builder.plan().clone();
    let mut order = match prepare_submission_order_from_match_v2(
        prepared,
        platform_order_id.clone(),
        item_idempotency_identity,
        &plan,
    )? {
        PreparedSubmissionOrderV2::Rejected(reason) => {
            return Ok((
                builder.into_execution_drive(),
                PreparedSubmissionExecutionDeltaResultV2 {
                    outcome: SubmissionItemOutcomeV1::RejectedNoEffect(reason),
                    order_feedbacks: Vec::new(),
                    trade_feedbacks: Vec::new(),
                    execution_changed: false,
                },
            ));
        }
        PreparedSubmissionOrderV2::Ready(order) => order,
    };
    let mut fill_records = taker_fill_records(
        &platform_order_id,
        &prepared.condition_id.0,
        &prepared.token_id.0,
        prepared.effective_processing_at_utc_ms,
        &plan,
    )?;
    let fee_units = allocate_immediate_taker_fee_against_rules(rule_snapshot, &mut fill_records)?;
    order.immediate_taker_fee_encumbered_units = fee_units;
    let required_units = order.accepted_quote_units.checked_add(fee_units).ok_or(
        SubmissionProcessingErrorV1::InternalInvariant("订单本金与手续费之和溢出"),
    )?;
    if builder.candidate_available_pusd_units() < required_units {
        return Ok((
            builder.into_execution_drive(),
            PreparedSubmissionExecutionDeltaResultV2 {
                outcome: SubmissionItemOutcomeV1::RejectedNoEffect(
                    SubmissionRejectedReasonV1::InsufficientAvailablePusd,
                ),
                order_feedbacks: Vec::new(),
                trade_feedbacks: Vec::new(),
                execution_changed: false,
            },
        ));
    }
    let accepted_order_status = if order.open_base_units > 0 {
        simulated_order_status("LIVE")
    } else {
        simulated_order_status("MATCHED")
    };
    let lifecycle_account_rule = &rule_snapshot
        .snapshot()
        .project_account_rules
        .lifecycle_account_behavior
        .value;
    let (execution, effects) =
        builder.finish_new_order(order, fill_records, finality_policy, lifecycle_account_rule)?;
    let mut account_delta_references = effects
        .order_commit_effects()
        .account_deltas
        .iter()
        .map(|delta| AccountDeltaReferenceV1::from(delta.as_ref()))
        .collect::<Vec<_>>();
    if let Some(effect) = effects.venue_dust_effect() {
        account_delta_references.push(AccountDeltaReferenceV1::from(effect.account_delta.as_ref()));
    }
    let mut order_feedbacks = effects
        .order_commit_effects()
        .account_deltas
        .iter()
        .map(|delta| OrderLifecycleFeedbackSeedV1 {
            platform_order_id: effects.order().platform_order_id.clone(),
            condition_id: effects.order().condition_id.clone(),
            token_id: effects.order().token_id.clone(),
            event_kind: match delta.reason {
                contracts::PlatformAccountDeltaReasonV1::OrderAcceptedEncumbranceApplied => {
                    OrderLifecycleEventKindV1::OrderAccepted
                }
                contracts::PlatformAccountDeltaReasonV1::FakUnspentEncumbranceReleased => {
                    OrderLifecycleEventKindV1::FakUnspentReleased
                }
                _ => unreachable!("订单提交只能形成接受或 FAK 未花释放变化"),
            },
            order_status: accepted_order_status.clone(),
            venue_dust_closed_base_units: 0,
            venue_dust_released_quote_units: 0,
            market_resolved_canceled_base_units: 0,
            market_resolved_released_quote_units: 0,
            account_delta: Arc::clone(delta),
        })
        .collect::<Vec<_>>();
    if let Some(effect) = effects.venue_dust_effect() {
        order_feedbacks.push(OrderLifecycleFeedbackSeedV1 {
            platform_order_id: effect.platform_order_id.clone(),
            condition_id: effect.condition_id.clone(),
            token_id: effect.token_id.clone(),
            event_kind: OrderLifecycleEventKindV1::VenueDustTerminal,
            order_status: simulated_order_status("VENUE_DUST_TERMINAL"),
            venue_dust_closed_base_units: effect.closed_base_units,
            venue_dust_released_quote_units: effect.released_open_quote_units,
            market_resolved_canceled_base_units: 0,
            market_resolved_released_quote_units: 0,
            account_delta: Arc::clone(&effect.account_delta),
        });
    }
    let outcome = SubmissionItemOutcomeV1::Accepted(Box::new(accepted_submission_item(
        effects.order(),
        effects.fills(),
        account_delta_references,
    )?));
    Ok((
        execution,
        PreparedSubmissionExecutionDeltaResultV2 {
            outcome,
            order_feedbacks,
            trade_feedbacks: effects.trade_finality_effects().to_vec(),
            execution_changed: true,
        },
    ))
}

fn accepted_submission_item(
    order: &SimOrderRecordV1,
    fills: &[SimFillRecordV1],
    account_deltas: Vec<AccountDeltaReferenceV1>,
) -> Result<AcceptedSubmissionItemV1, SubmissionProcessingErrorV1> {
    let fills = fills
        .iter()
        .map(|fill| {
            Ok(SubmissionFillV1 {
                simulated_trade_id: fill.trade_id.clone(),
                source_price_pusd_per_share: fill.price_pusd_per_share,
                base_quantity_shares: decimal_from_micro_units_v1(fill.base_units)?,
                quote_amount_pusd: decimal_from_micro_units_v1(fill.quote_units)?,
            })
        })
        .collect::<Result<Vec<_>, MatchingMathErrorV1>>()?;
    let terminal_reason = match order.terminal_reason {
        Some(SimOrderTerminalReasonV1::FakCompleted) => {
            Some(SubmissionTerminalReasonV1::FakCompleted)
        }
        Some(SimOrderTerminalReasonV1::VenueDustTerminal) => {
            Some(SubmissionTerminalReasonV1::VenueDustTerminal)
        }
        Some(SimOrderTerminalReasonV1::MarketResolvedCanceled) => {
            return Err(SubmissionProcessingErrorV1::InternalInvariant(
                "新订单提交响应不得已处于判定关闭终态",
            ));
        }
        None => None,
    };
    let measurement = if let Some(accepted_base_units) = order.accepted_base_units {
        SubmissionMeasurementV1::Base(BaseSubmissionMeasurementV1 {
            accepted_base_quantity_shares: decimal_from_micro_units_v1(accepted_base_units)?,
            matched_base_quantity_shares: decimal_from_micro_units_v1(order.matched_base_units)?,
            open_base_quantity_shares: decimal_from_micro_units_v1(order.open_base_units)?,
            venue_dust_closed_base_quantity_shares: decimal_from_micro_units_v1(
                order.venue_dust_closed_base_units,
            )?,
            order_type_terminated_base_quantity_shares: Decimal::ZERO,
            accepted_quote_amount_pusd: decimal_from_micro_units_v1(order.accepted_quote_units)?,
            matched_quote_amount_pusd: decimal_from_micro_units_v1(order.matched_quote_units)?,
            open_encumbered_quote_amount_pusd: decimal_from_micro_units_v1(order.open_quote_units)?,
            venue_dust_released_quote_amount_pusd: decimal_from_micro_units_v1(
                order.venue_dust_released_quote_units,
            )?,
            released_price_improvement_quote_amount_pusd: decimal_from_micro_units_v1(
                order.released_quote_units,
            )?,
            immediate_taker_fee_encumbered_pusd: decimal_from_micro_units_v1(
                order.immediate_taker_fee_encumbered_units,
            )?,
        })
    } else {
        SubmissionMeasurementV1::QuoteBudget(QuoteBudgetSubmissionMeasurementV1 {
            accepted_quote_budget_pusd: decimal_from_micro_units_v1(order.accepted_quote_units)?,
            used_quote_amount_pusd: decimal_from_micro_units_v1(order.matched_quote_units)?,
            released_or_unspent_quote_amount_pusd: decimal_from_micro_units_v1(
                order.released_quote_units,
            )?,
            actual_matched_base_quantity_shares: decimal_from_micro_units_v1(
                order.matched_base_units,
            )?,
            sdk_taker_amount_audit_shares: decimal_from_micro_units_v1(
                order.sdk_taker_amount_audit_base_units.ok_or(
                    SubmissionProcessingErrorV1::InternalInvariant(
                        "quote 预算订单缺少 SDK base 审计投影",
                    ),
                )?,
            )?,
            immediate_taker_fee_encumbered_pusd: decimal_from_micro_units_v1(
                order.immediate_taker_fee_encumbered_units,
            )?,
        })
    };
    Ok(AcceptedSubmissionItemV1 {
        simulated_platform_order_id: order.platform_order_id.clone(),
        platform_order_status: if order.venue_dust_closed_base_units > 0 {
            SubmissionPlatformOrderStatusV1::VenueDustTerminal
        } else if order.open_base_units > 0 {
            SubmissionPlatformOrderStatusV1::Live
        } else if order.matched_base_units > 0 {
            SubmissionPlatformOrderStatusV1::Matched
        } else {
            return Err(SubmissionProcessingErrorV1::InternalInvariant(
                "无开放量、无成交量且无订单类型终态的订单状态非法",
            ));
        },
        fills,
        terminal_reason,
        measurement,
        account_deltas,
    })
}

fn fee_rule_identity(session: &SimSession) -> SubmissionFeeRuleIdentityV1 {
    let rule = &session
        .rule_snapshot()
        .snapshot()
        .documented_platform_rules
        .fee_computation
        .value;
    SubmissionFeeRuleIdentityV1 {
        formula_version: rule.formula_version.clone(),
        aggregation_version: SUBMISSION_FEE_AGGREGATION_V1.to_owned(),
        precision_decimal_places: rule.precision_decimal_places,
        minimum_nonzero_fee_pusd: rule.minimum_nonzero_fee_pusd.value(),
        builder_fee_pusd: Decimal::ZERO,
    }
}

enum ScheduledLifecycleFeedbackV1 {
    Order(OrderLifecycleFeedbackSeedV1),
    Trade(TradeFinalityTransitionEffectV1),
    Settlement(SettlementLifecycleFeedbackSeedV1),
}

impl ScheduledLifecycleFeedbackV1 {
    fn platform_effective_at_utc_ms(&self) -> i64 {
        match self {
            Self::Order(feedback) => feedback.account_delta.platform_effective_at_utc_ms,
            Self::Trade(feedback) => feedback.platform_event_at_utc_ms,
            Self::Settlement(feedback) => feedback.platform_event_at_utc_ms,
        }
    }
}

trait PreparedLifecycleTimingSessionV2 {
    fn prepare_next_lifecycle_feedback_timing_v2(
        &mut self,
        feedback_id: String,
        platform_event_at_utc_ms: i64,
    ) -> Result<LifecycleFeedbackTimingV1, SessionError>;
}

impl PreparedLifecycleTimingSessionV2 for crate::session::PreparedScheduledSessionDriveV2<'_> {
    fn prepare_next_lifecycle_feedback_timing_v2(
        &mut self,
        feedback_id: String,
        platform_event_at_utc_ms: i64,
    ) -> Result<LifecycleFeedbackTimingV1, SessionError> {
        self.prepare_next_lifecycle_feedback_timing(feedback_id, platform_event_at_utc_ms)
    }
}

impl PreparedLifecycleTimingSessionV2 for crate::session::PreparedClosedBucketSessionDriveV2<'_> {
    fn prepare_next_lifecycle_feedback_timing_v2(
        &mut self,
        feedback_id: String,
        platform_event_at_utc_ms: i64,
    ) -> Result<LifecycleFeedbackTimingV1, SessionError> {
        self.prepare_next_lifecycle_feedback_timing(feedback_id, platform_event_at_utc_ms)
    }
}

fn record_prepared_order_lifecycle_feedback_v2<S: PreparedLifecycleTimingSessionV2>(
    session_id: &str,
    session: &mut S,
    outbox: &mut PreparedLifecycleOutboxDeltaV2<'_>,
    reservation: &LifecycleBatchReservationV1,
    feedback: OrderLifecycleFeedbackSeedV1,
) -> Result<Option<DurablePrivateOutputDraftV1>, SessionError> {
    let feedback_id = order_lifecycle_feedback_id_v2(
        session_id,
        &feedback.platform_order_id,
        feedback.event_kind,
    );
    let timing = session.prepare_next_lifecycle_feedback_timing_v2(
        feedback_id.clone(),
        feedback.account_delta.platform_effective_at_utc_ms,
    )?;
    let delivery_id = order_lifecycle_delivery_id_v1(session_id, &feedback_id);
    outbox.record_for_batch(
        reservation,
        LifecycleFeedbackDraftV1::Order(OrderLifecycleFeedbackDraftV1 {
            feedback_id,
            delivery_id,
            account_instance_key: feedback.account_delta.account_instance_key.clone(),
            session_id: session_id.to_owned(),
            timing,
            platform_order_id: feedback.platform_order_id,
            condition_id: ConditionId(feedback.condition_id),
            token_id: TokenId(feedback.token_id),
            event_kind: feedback.event_kind,
            order_status: feedback.order_status,
            venue_dust_closed_base_units: feedback.venue_dust_closed_base_units,
            venue_dust_released_quote_units: feedback.venue_dust_released_quote_units,
            market_resolved_canceled_base_units: feedback.market_resolved_canceled_base_units,
            market_resolved_released_quote_units: feedback.market_resolved_released_quote_units,
            account_delta: feedback.account_delta,
        }),
    )
}

fn record_prepared_trade_lifecycle_feedback_v2<S: PreparedLifecycleTimingSessionV2>(
    session_id: &str,
    account_instance_key: &AccountInstanceKeyV1,
    session: &mut S,
    outbox: &mut PreparedLifecycleOutboxDeltaV2<'_>,
    reservation: &LifecycleBatchReservationV1,
    feedback: TradeFinalityTransitionEffectV1,
) -> Result<Option<DurablePrivateOutputDraftV1>, SessionError> {
    let mut feedback_id_hash = CanonicalHasher::new("SIM_TRADE_LIFECYCLE_FEEDBACK_ID_V1");
    feedback_id_hash.text(&feedback.trade_id);
    feedback_id_hash.text(trade_finality_state_identity(feedback.finality_state));
    feedback_id_hash.i64(feedback.platform_event_at_utc_ms);
    let feedback_id = feedback_id_hash.finish().0;
    let timing = session.prepare_next_lifecycle_feedback_timing_v2(
        feedback_id.clone(),
        feedback.platform_event_at_utc_ms,
    )?;
    let mut delivery_id_hash = CanonicalHasher::new("SIM_TRADE_LIFECYCLE_DELIVERY_ID_V1");
    delivery_id_hash.text(session_id);
    delivery_id_hash.text(&feedback_id);
    let delivery_id = delivery_id_hash.finish().0;
    outbox.record_for_batch(
        reservation,
        LifecycleFeedbackDraftV1::Trade(TradeLifecycleFeedbackDraftV1 {
            feedback_id,
            delivery_id,
            account_instance_key: account_instance_key.clone(),
            session_id: session_id.to_owned(),
            timing,
            simulated_trade_id: feedback.trade_id,
            platform_order_id: feedback.platform_order_id,
            condition_id: ConditionId(feedback.condition_id),
            token_id: TokenId(feedback.token_id),
            status: simulated_trade_status(trade_finality_state_identity(feedback.finality_state)),
            economic_disposition: project_trade_economic_disposition(feedback.economic_disposition),
            liquidity_role: match feedback.liquidity_role {
                SimLiquidityRoleV1::Taker => TradeLiquidityRoleV1::Taker,
                SimLiquidityRoleV1::MakerInferred => TradeLiquidityRoleV1::MakerInferred,
            },
            base_units: feedback.base_units,
            quote_units: feedback.quote_units,
            immediate_taker_fee_units: feedback.immediate_taker_fee_units,
            economic_application_delta: feedback
                .economic_application_delta
                .as_deref()
                .map(AccountDeltaReferenceV1::from),
            account_delta: feedback.account_delta,
        }),
    )
}

fn record_prepared_settlement_lifecycle_feedback_v2<S: PreparedLifecycleTimingSessionV2>(
    session_id: &str,
    account_instance_key: &AccountInstanceKeyV1,
    session: &mut S,
    outbox: &mut PreparedLifecycleOutboxDeltaV2<'_>,
    reservation: &LifecycleBatchReservationV1,
    feedback: SettlementLifecycleFeedbackSeedV1,
) -> Result<Option<DurablePrivateOutputDraftV1>, SessionError> {
    let mut feedback_id_hash = CanonicalHasher::new("SIM_SETTLEMENT_LIFECYCLE_FEEDBACK_ID_V1");
    feedback_id_hash.text(&feedback.settlement_identity);
    feedback_id_hash.i64(feedback.platform_event_at_utc_ms);
    let feedback_id = feedback_id_hash.finish().0;
    let timing = session.prepare_next_lifecycle_feedback_timing_v2(
        feedback_id.clone(),
        feedback.platform_event_at_utc_ms,
    )?;
    let mut delivery_id_hash = CanonicalHasher::new("SIM_SETTLEMENT_LIFECYCLE_DELIVERY_ID_V1");
    delivery_id_hash.text(session_id);
    delivery_id_hash.text(&feedback_id);
    let delivery_id = delivery_id_hash.finish().0;
    outbox.record_for_batch(
        reservation,
        LifecycleFeedbackDraftV1::Settlement(SettlementLifecycleFeedbackDraftV1 {
            feedback_id,
            delivery_id,
            account_instance_key: account_instance_key.clone(),
            session_id: session_id.to_owned(),
            timing,
            settlement_identity: feedback.settlement_identity,
            event: feedback.event,
        }),
    )
}

fn record_prepared_lifecycle_feedback_v2<S: PreparedLifecycleTimingSessionV2>(
    session_id: &str,
    account_instance_key: &AccountInstanceKeyV1,
    session: &mut S,
    outbox: &mut PreparedLifecycleOutboxDeltaV2<'_>,
    reservation: &LifecycleBatchReservationV1,
    feedback: ScheduledLifecycleFeedbackV1,
) -> Result<Option<DurablePrivateOutputDraftV1>, MarketEventErrorV1> {
    Ok(match feedback {
        ScheduledLifecycleFeedbackV1::Order(feedback) => {
            record_prepared_order_lifecycle_feedback_v2(
                session_id,
                session,
                outbox,
                reservation,
                feedback,
            )?
        }
        ScheduledLifecycleFeedbackV1::Trade(feedback) => {
            record_prepared_trade_lifecycle_feedback_v2(
                session_id,
                account_instance_key,
                session,
                outbox,
                reservation,
                feedback,
            )?
        }
        ScheduledLifecycleFeedbackV1::Settlement(feedback) => {
            record_prepared_settlement_lifecycle_feedback_v2(
                session_id,
                account_instance_key,
                session,
                outbox,
                reservation,
                feedback,
            )?
        }
    })
}

fn submission_processing_error_from_market_event_v2(
    error: MarketEventErrorV1,
) -> SubmissionProcessingErrorV1 {
    match error {
        MarketEventErrorV1::Session(error) => SubmissionProcessingErrorV1::Session(error),
        other => {
            SubmissionProcessingErrorV1::Session(SessionError::ExecutionState(other.to_string()))
        }
    }
}

fn prepare_new_cancel_effect_record_v2<'a>(
    mut scheduled: crate::session::PreparedScheduledSessionDriveV2<'a>,
    query: &PreparedQueryStateDeltaV2<'_>,
    request: &PendingDomainRequestV1,
    cancel_groups: Option<&[CancelTargetInputGroupV1]>,
    root_effect_identity: &str,
    originating_global_request_id: &str,
    formed_at_utc_ms: i64,
) -> Result<
    (
        crate::session::PreparedScheduledSessionDriveV2<'a>,
        CancelEffectRecordV1,
        Vec<OrderLifecycleFeedbackSeedV1>,
    ),
    SubmissionProcessingErrorV1,
> {
    let mut targets = Vec::new();
    let mut feedbacks = Vec::new();
    match request {
        PendingDomainRequestV1::CancelOrder(_) | PendingDomainRequestV1::CancelOrders(_) => {
            let groups = cancel_groups.ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "逐目标撤单缺少预计算目标分组",
            ))?;
            targets.reserve(groups.len());
            for group in groups {
                let target_effect_identity = cancel_target_effect_identity(
                    root_effect_identity,
                    &group.platform_order_id,
                    u64::from(group.unique_target_ordinal),
                );
                let order = scheduled
                    .execution_candidate()
                    .candidate_order(&group.platform_order_id)
                    .cloned();
                let hot_order_visible = order
                    .as_ref()
                    .map(|order| query.hot_order_is_query_visible(order))
                    .transpose()?
                    .unwrap_or(false);
                let disposition = if hot_order_visible {
                    let (next, disposition) = scheduled.prepare_caller_cancel_remainder(
                        &group.platform_order_id,
                        formed_at_utc_ms,
                        &Sha256Hex(target_effect_identity.clone()),
                    )?;
                    scheduled = next;
                    disposition
                } else if query
                    .retained_terminal_order(&group.platform_order_id)
                    .is_some()
                {
                    CancelOrderStateDispositionV1::NoCancellableRemainder
                } else {
                    CancelOrderStateDispositionV1::NotFound
                };
                let (outcome, feedback) = cancel_target_outcome(disposition, order.as_ref())?;
                feedbacks.extend(feedback);
                targets.push(CancelTargetEffectV1 {
                    platform_order_id: group.platform_order_id.clone(),
                    effect_identity: target_effect_identity,
                    outcome,
                });
            }
        }
        PendingDomainRequestV1::CancelAllOrders(_) => {
            let mut target_ids = Vec::new();
            for order in scheduled.execution_candidate().candidate_orders() {
                let active_base_units = order
                    .pending_maker_depletion_base_units
                    .checked_add(order.open_base_units)
                    .ok_or(MatchingMathErrorV1::ArithmeticOverflow)?;
                if active_base_units > 0 {
                    target_ids.push(order.platform_order_id.clone());
                }
            }
            target_ids.sort();
            targets.reserve(target_ids.len());
            for (ordinal, platform_order_id) in target_ids.into_iter().enumerate() {
                let ordinal = u64::try_from(ordinal).map_err(|_| {
                    SubmissionProcessingErrorV1::InternalInvariant("全撤活动目标序号超出 u64 边界")
                })?;
                let effect_identity = cancel_target_effect_identity(
                    root_effect_identity,
                    &platform_order_id,
                    ordinal,
                );
                let order = scheduled
                    .execution_candidate()
                    .candidate_order(&platform_order_id)
                    .cloned();
                let (next, disposition) = scheduled.prepare_caller_cancel_remainder(
                    &platform_order_id,
                    formed_at_utc_ms,
                    &Sha256Hex(effect_identity.clone()),
                )?;
                scheduled = next;
                let (outcome, feedback) = cancel_target_outcome(disposition, order.as_ref())?;
                if !matches!(outcome, CancelTargetOutcomeV1::Canceled(_)) {
                    return Err(SubmissionProcessingErrorV1::InternalInvariant(
                        "全撤冻结活动目标在同一候选中失去可撤余量",
                    ));
                }
                feedbacks.extend(feedback);
                targets.push(CancelTargetEffectV1 {
                    platform_order_id,
                    effect_identity,
                    outcome,
                });
            }
        }
        _ => {
            return Err(SubmissionProcessingErrorV1::InternalInvariant(
                "非撤单请求进入撤单效果准备",
            ));
        }
    }
    Ok((
        scheduled,
        CancelEffectRecordV1 {
            originating_global_request_id: originating_global_request_id.to_owned(),
            formed_at_utc_ms,
            targets,
        },
        feedbacks,
    ))
}

fn cancel_direct_response_part_v2(
    request: &PendingDomainRequestV1,
    action: &QueuedLogicalActionV1,
    cancel_groups: Option<&[CancelTargetInputGroupV1]>,
    record: &CancelEffectRecordV1,
) -> Result<DirectResponsePartV1, SubmissionProcessingErrorV1> {
    let effect_disposition = if record.originating_global_request_id == action.global_request_id {
        CancelEffectDispositionV1::NewEffect
    } else {
        CancelEffectDispositionV1::ExistingEffect
    };
    match request {
        PendingDomainRequestV1::CancelOrder(_) | PendingDomainRequestV1::CancelOrders(_) => {
            let groups = cancel_groups.ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "逐目标撤单缺少预计算目标分组",
            ))?;
            if record.targets.len() != groups.len() {
                return Err(SubmissionProcessingErrorV1::InternalInvariant(
                    "撤单幂等效果目标数量冲突",
                ));
            }
            let group = groups
                .get(usize::from(action.key.batch_item_ordinal))
                .filter(|group| group.unique_target_ordinal == action.key.batch_item_ordinal)
                .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                    "撤单动作没有对应唯一目标",
                ))?;
            let target = record
                .targets
                .get(usize::from(group.unique_target_ordinal))
                .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                    "撤单幂等效果缺少目标结果",
                ))?;
            if target.platform_order_id != group.platform_order_id {
                return Err(SubmissionProcessingErrorV1::InternalInvariant(
                    "撤单幂等效果目标冲突",
                ));
            }
            Ok(DirectResponsePartV1::CancelTarget(CancelTargetResponseV1 {
                platform_order_id: target.platform_order_id.clone(),
                target_ordinal: u64::from(group.unique_target_ordinal),
                input_item_refs: group.input_item_refs.clone(),
                effective_processing_at_utc_ms: action.key.effective_processing_at_utc_ms,
                cancel_effect_identity: target.effect_identity.clone(),
                cancel_effect_formed_at_utc_ms: record.formed_at_utc_ms,
                cancel_effect_disposition: effect_disposition,
                outcome: target.outcome.clone(),
            }))
        }
        PendingDomainRequestV1::CancelAllOrders(_) => {
            let targets = record
                .targets
                .iter()
                .enumerate()
                .map(|(ordinal, target)| {
                    Ok(CancelTargetResponseV1 {
                        platform_order_id: target.platform_order_id.clone(),
                        target_ordinal: u64::try_from(ordinal).map_err(|_| {
                            SubmissionProcessingErrorV1::InternalInvariant(
                                "全撤响应目标序号超出 u64 边界",
                            )
                        })?,
                        input_item_refs: Vec::new(),
                        effective_processing_at_utc_ms: action.key.effective_processing_at_utc_ms,
                        cancel_effect_identity: target.effect_identity.clone(),
                        cancel_effect_formed_at_utc_ms: record.formed_at_utc_ms,
                        cancel_effect_disposition: effect_disposition,
                        outcome: target.outcome.clone(),
                    })
                })
                .collect::<Result<Vec<_>, SubmissionProcessingErrorV1>>()?;
            Ok(DirectResponsePartV1::CancelAll {
                effective_processing_at_utc_ms: action.key.effective_processing_at_utc_ms,
                targets,
            })
        }
        _ => Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非撤单请求进入撤单直接响应准备",
        )),
    }
}

fn prepare_cancel_execution_drive_v2<'a>(
    execution_session: &'a mut SimExecutionSessionV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedCancelExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let SimExecutionSessionV1 {
        session,
        pending_requests,
        cancel_effect_records,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        ..
    } = execution_session;
    prepare_cancel_execution_drive_fields_v2(
        session,
        pending_requests,
        cancel_effect_records,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        requested_cutoff_utc_ms,
        occupied_lifecycle_capacity_leases,
    )
}

fn prepare_cancel_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    pending_requests: &BTreeMap<String, PendingDomainRequestV1>,
    cancel_effect_records: &'a mut BTreeMap<String, CancelEffectRecordV1>,
    query_state: &'a mut QueryStateV1,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedCancelExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let rule_snapshot_sha256 = session.rule_snapshot().file_sha256().clone();
    let scenario_sha256 = session.scenario().scenario_sha256().clone();
    let fee_rule = fee_rule_identity(session);
    let session_spec = session.session_spec().clone();
    let prefix = prepare_execution_drive_prefix_v2(session, requested_cutoff_utc_ms, true)
        .map_err(submission_processing_error_from_market_event_v2)?;
    let first_action =
        prefix
            .current_action()
            .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "撤单执行准备缺少到期逻辑动作",
            ))?;
    let request = pending_requests
        .get(&first_action.global_request_id)
        .cloned()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "撤单执行准备缺少领域请求",
        ))?;
    validate_action_mapping(&request, &first_action)?;
    if !matches!(
        request,
        PendingDomainRequestV1::CancelOrder(_)
            | PendingDomainRequestV1::CancelOrders(_)
            | PendingDomainRequestV1::CancelAllOrders(_)
    ) {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非撤单请求进入撤单执行准备",
        ));
    }
    let (idempotency_key, payload_sha256) = mutation_binding(&request).ok_or(
        SubmissionProcessingErrorV1::InternalInvariant("撤单动作缺少变更幂等绑定"),
    )?;
    let request_idempotency_identity =
        cancel_request_idempotency_identity(&session_spec, &idempotency_key);
    let root_effect_identity =
        cancel_item_effect_identity(&request_idempotency_identity, &payload_sha256);
    let cancel_groups = match &request {
        PendingDomainRequestV1::CancelOrder(_) | PendingDomainRequestV1::CancelOrders(_) => {
            Some(cancel_target_groups(&request)?)
        }
        PendingDomainRequestV1::CancelAllOrders(_) => None,
        _ => unreachable!("撤单请求种类已经在准备前验证"),
    };

    let mut lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let request_reservation = lifecycle.reserve_request(
        &first_action.global_request_id,
        first_action.key.effective_processing_at_utc_ms,
        occupied_lifecycle_capacity_leases,
    )?;
    let materialized = materialize_execution_drive_prefix_v2(
        prefix,
        query_state,
        lifecycle,
        Some(&first_action.global_request_id),
        occupied_lifecycle_capacity_leases,
    )
    .map_err(submission_processing_error_from_market_event_v2)?;
    let MaterializedExecutionDrivePrefixV2 {
        session_id,
        mut scheduled,
        query,
        mut lifecycle,
        terminal_projection_condition_ids,
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        mut after_query_projection_revision,
        actual_cutoff_utc_ms,
        mut new_private_output_drafts,
        scheduled_state_changed: _,
    } = materialized;
    let mut cancel_effects = PreparedCancelEffectRecordsDeltaV2::prepare(
        cancel_effect_records,
        root_effect_identity.clone(),
    );
    let mut direct =
        direct_response_outbox.prepare_entry_delta_v2(&first_action.global_request_id)?;
    let mut logical_action_results = Vec::new();
    let mut cancellation_projection_changed = false;

    while let Some(action) = scheduled.current_action() {
        validate_action_mapping(&request, &action)?;
        let resolution = scheduled.prepare_mutation_resolution(
            &action.global_request_id,
            &action.action_identity,
            request_idempotency_identity.clone(),
            payload_sha256.clone(),
            root_effect_identity.clone(),
        )?;
        let new_effect = resolution.disposition == MutationResolutionDispositionV1::NewEffect;
        let mut caller_cancel_feedbacks = Vec::new();
        if new_effect {
            let (next, record, feedbacks) = prepare_new_cancel_effect_record_v2(
                scheduled,
                &query,
                &request,
                cancel_groups.as_deref(),
                &resolution.effect_identity,
                &action.global_request_id,
                action.key.effective_processing_at_utc_ms,
            )?;
            scheduled = next;
            cancellation_projection_changed = record
                .targets
                .iter()
                .any(|target| matches!(target.outcome, CancelTargetOutcomeV1::Canceled(_)));
            cancel_effects.prepare_new_record(record)?;
            caller_cancel_feedbacks = feedbacks;
        }
        let part = cancel_direct_response_part_v2(
            &request,
            &action,
            cancel_groups.as_deref(),
            cancel_effects.candidate_record().ok_or(
                SubmissionProcessingErrorV1::InternalInvariant("既有撤单幂等效果缺少终局结果"),
            )?,
        )?;
        logical_action_results.push(
            durable_logical_action_result(
                &action.global_request_id,
                &request,
                usize::from(action.key.batch_item_ordinal),
                scheduled.query_revision_for_request(&action.global_request_id),
                &part,
            )
            .map_err(|error| SessionError::Durability(error.to_string()))?,
        );
        for feedback in caller_cancel_feedbacks {
            if let Some(draft) = record_prepared_order_lifecycle_feedback_v2(
                &session_id,
                &mut scheduled,
                &mut lifecycle,
                &request_reservation,
                feedback,
            )? {
                new_private_output_drafts.push(draft);
            }
        }
        direct.record_part(part)?;
        scheduled.finish_current_action(&action.action_identity)?;
    }
    if !scheduled.request_completed() {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "撤单 composer 未完成同请求全部动作",
        ));
    }
    if cancellation_projection_changed
        && after_query_projection_revision == before_query_projection_revision
    {
        after_query_projection_revision = scheduled.advance_platform_state_revision_once()?;
    }
    lifecycle.complete_request(&first_action.global_request_id, &request_reservation)?;
    let platform_responded_at_utc_ms =
        direct
            .platform_responded_at()
            .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "撤单直接响应缺少平台响应时点",
            ))?;
    let private_emission_sequence = scheduled.next_private_emission_sequence()?;
    let transit = scheduled.prepare_complete_direct_response(
        &first_action.global_request_id,
        platform_responded_at_utc_ms,
        private_emission_sequence,
    )?;
    if let Some(draft) = direct.complete_draft(
        request.context().clone(),
        &transit,
        rule_snapshot_sha256,
        scenario_sha256,
        fee_rule,
    )? {
        new_private_output_drafts.push(draft);
    }
    let evidence = logical_transaction_evidence_from_after_values_v2(
        DurableTransactionFactV1::ExecutionAdvanced { session_id },
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        after_query_projection_revision,
        Some(actual_cutoff_utc_ms),
        before_private_schedule_through_utc_ms,
        logical_action_results,
        new_private_output_drafts,
    )?;
    Ok(PreparedCancelExecutionDriveV2 {
        scheduled,
        query,
        cancel_effects,
        direct,
        lifecycle,
        terminal_projection_condition_ids,
        evidence,
        recovery_operation: DurableRecoveryOperationV2::DriveExecutionThrough {
            effective_processing_at_utc_ms: actual_cutoff_utc_ms,
        },
        disposition: SubmissionDriveDispositionV1::ItemProcessed {
            request_completed: true,
        },
    })
}

fn prepare_post_execution_drive_v2<'a>(
    execution_session: &'a mut SimExecutionSessionV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedPostExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let SimExecutionSessionV1 {
        session,
        pending_requests,
        submission_effect_records,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        ..
    } = execution_session;
    prepare_post_execution_drive_fields_v2(
        session,
        pending_requests,
        submission_effect_records,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        requested_cutoff_utc_ms,
        occupied_lifecycle_capacity_leases,
    )
}

#[allow(clippy::too_many_arguments)]
fn prepare_post_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    pending_requests: &BTreeMap<String, PendingDomainRequestV1>,
    submission_effect_records: &'a mut BTreeMap<String, SubmissionEffectRecordV1>,
    query_state: &'a mut QueryStateV1,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedPostExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let session_spec = session.session_spec().clone();
    let account_instance_key = session.execution_state().account_instance_key().clone();
    let rule_snapshot = Arc::clone(session.rule_snapshot());
    let finality_policy = Arc::clone(session.finality_policy());
    let rule_snapshot_sha256 = rule_snapshot.file_sha256().clone();
    let scenario_sha256 = session.scenario().scenario_sha256().clone();
    let fee_rule = fee_rule_identity(session);
    let peeked_action = session
        .first_pending_action_through(requested_cutoff_utc_ms)
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "Post 执行准备缺少到期逻辑动作",
        ))?;
    let request = pending_requests
        .get(&peeked_action.global_request_id)
        .cloned()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "Post 执行准备缺少领域请求",
        ))?;
    validate_action_mapping(&request, &peeked_action)?;
    if !matches!(
        request,
        PendingDomainRequestV1::PostOrder(_) | PendingDomainRequestV1::PostOrders(_)
    ) {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非 Post 请求进入 Post 执行准备",
        ));
    }
    let item = SimExecutionSessionV1::post_item_for_action(&request, &peeked_action)?.clone();
    let candidate_best_ask = session
        .execution_state()
        .best_executable_ask(&item.order.condition_id.0, &item.order.token_id.0);
    let admission = SimExecutionSessionV1::prepare_submission_against_candidate(
        session,
        &peeked_action,
        &request,
        candidate_best_ask,
    );

    let prefix = prepare_execution_drive_prefix_v2(session, requested_cutoff_utc_ms, false)
        .map_err(submission_processing_error_from_market_event_v2)?;
    let action = prefix
        .current_action()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "Post 执行准备缺少到期逻辑动作",
        ))?;
    if action != peeked_action {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "Post 执行准备的队首动作发生变化",
        ));
    }
    let (idempotency_key, payload_sha256) = mutation_binding(&request).ok_or(
        SubmissionProcessingErrorV1::InternalInvariant("Post 动作缺少变更幂等绑定"),
    )?;
    let item_idempotency_identity = submission_item_idempotency_identity(
        &session_spec,
        &idempotency_key,
        action.key.batch_item_ordinal,
    );
    let effect_identity =
        submission_item_effect_identity(&item_idempotency_identity, &payload_sha256);

    let mut lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let request_reservation = lifecycle.reserve_request(
        &action.global_request_id,
        action.key.effective_processing_at_utc_ms,
        occupied_lifecycle_capacity_leases,
    )?;
    let materialized = materialize_execution_drive_prefix_v2(
        prefix,
        query_state,
        lifecycle,
        Some(&action.global_request_id),
        occupied_lifecycle_capacity_leases,
    )
    .map_err(submission_processing_error_from_market_event_v2)?;
    let MaterializedExecutionDrivePrefixV2 {
        session_id,
        mut scheduled,
        query,
        mut lifecycle,
        terminal_projection_condition_ids,
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        mut after_query_projection_revision,
        actual_cutoff_utc_ms,
        mut new_private_output_drafts,
        scheduled_state_changed: _,
    } = materialized;
    let resolution = scheduled.prepare_mutation_resolution(
        &action.global_request_id,
        &action.action_identity,
        item_idempotency_identity.clone(),
        payload_sha256,
        effect_identity.clone(),
    )?;
    let mut submission_effect =
        PreparedSubmissionEffectRecordDeltaV2::prepare(submission_effect_records, effect_identity);
    let mut order_feedbacks = Vec::new();
    let mut trade_feedbacks = Vec::new();
    let mut execution_changed = false;
    let effect_disposition = match resolution.disposition {
        MutationResolutionDispositionV1::ExistingEffect => {
            SubmissionEffectDispositionV1::ExistingEffect
        }
        MutationResolutionDispositionV1::NewEffect => {
            let outcome = match admission? {
                SubmissionAdmissionDecisionV1::Prepared(prepared) => {
                    let (next_scheduled, result) =
                        scheduled.map_execution_candidate(|execution| {
                            prepare_submission_execution_delta_v2(
                                execution,
                                &session_spec,
                                rule_snapshot.as_ref(),
                                finality_policy.as_ref(),
                                &prepared,
                                &resolution.effect_identity,
                                &item_idempotency_identity,
                            )
                        })?;
                    scheduled = next_scheduled;
                    order_feedbacks = result.order_feedbacks;
                    trade_feedbacks = result.trade_feedbacks;
                    execution_changed = result.execution_changed;
                    result.outcome
                }
                SubmissionAdmissionDecisionV1::RejectedNoEffect(reason) => {
                    SubmissionItemOutcomeV1::RejectedNoEffect(map_submission_rejection(reason))
                }
                SubmissionAdmissionDecisionV1::EvidenceUnknownNoEffect(reason) => {
                    SubmissionItemOutcomeV1::EvidenceUnknownNoEffect(map_submission_evidence(
                        reason,
                    ))
                }
            };
            submission_effect.prepare_new_record(SubmissionEffectRecordV1 {
                outcome,
                formed_at_utc_ms: action.key.effective_processing_at_utc_ms,
            })?;
            SubmissionEffectDispositionV1::NewEffect
        }
    };
    let effect_record = submission_effect.candidate_record().ok_or(
        SubmissionProcessingErrorV1::InternalInvariant("既有提交幂等效果缺少终局结果"),
    )?;
    let part = DirectResponsePartV1::Submission(SubmissionResponseItemV1 {
        item_id: item.item_id,
        batch_item_ordinal: action.key.batch_item_ordinal,
        condition_id: item.order.condition_id,
        token_id: item.order.token_id,
        effective_processing_at_utc_ms: action.key.effective_processing_at_utc_ms,
        submission_effect_identity: resolution.effect_identity,
        submission_effect_formed_at_utc_ms: effect_record.formed_at_utc_ms,
        submission_effect_disposition: effect_disposition,
        outcome: effect_record.outcome.clone(),
    });
    if execution_changed && after_query_projection_revision == before_query_projection_revision {
        after_query_projection_revision = scheduled.advance_platform_state_revision_once()?;
    }
    let logical_action_result = durable_logical_action_result(
        &action.global_request_id,
        &request,
        usize::from(action.key.batch_item_ordinal),
        scheduled.query_revision_for_request(&action.global_request_id),
        &part,
    )
    .map_err(|error| SessionError::Durability(error.to_string()))?;
    for feedback in order_feedbacks {
        if let Some(draft) = record_prepared_order_lifecycle_feedback_v2(
            &session_id,
            &mut scheduled,
            &mut lifecycle,
            &request_reservation,
            feedback,
        )? {
            new_private_output_drafts.push(draft);
        }
    }
    for feedbacks in trade_feedbacks {
        if let Some(draft) = record_prepared_trade_lifecycle_feedback_v2(
            &session_id,
            &account_instance_key,
            &mut scheduled,
            &mut lifecycle,
            &request_reservation,
            feedbacks.trade_feedback,
        )? {
            new_private_output_drafts.push(draft);
        }
        for settlement in feedbacks.settlement_feedbacks {
            if let Some(draft) = record_prepared_settlement_lifecycle_feedback_v2(
                &session_id,
                &account_instance_key,
                &mut scheduled,
                &mut lifecycle,
                &request_reservation,
                settlement_lifecycle_feedback_seed(settlement)?,
            )? {
                new_private_output_drafts.push(draft);
            }
        }
    }
    let mut direct = direct_response_outbox.prepare_entry_delta_v2(&action.global_request_id)?;
    direct.record_part(part)?;
    scheduled.finish_current_action(&action.action_identity)?;
    let request_completed = scheduled.request_completed();
    if request_completed {
        lifecycle.complete_request(&action.global_request_id, &request_reservation)?;
        let platform_responded_at_utc_ms = direct.platform_responded_at().ok_or(
            SubmissionProcessingErrorV1::InternalInvariant("Post 直接响应缺少平台响应时点"),
        )?;
        let private_emission_sequence = scheduled.next_private_emission_sequence()?;
        let transit = scheduled.prepare_complete_direct_response(
            &action.global_request_id,
            platform_responded_at_utc_ms,
            private_emission_sequence,
        )?;
        if let Some(draft) = direct.complete_draft(
            request.context().clone(),
            &transit,
            rule_snapshot_sha256,
            scenario_sha256,
            fee_rule,
        )? {
            new_private_output_drafts.push(draft);
        }
    }
    let evidence = logical_transaction_evidence_from_after_values_v2(
        DurableTransactionFactV1::ExecutionAdvanced { session_id },
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        after_query_projection_revision,
        Some(actual_cutoff_utc_ms),
        before_private_schedule_through_utc_ms,
        vec![logical_action_result],
        new_private_output_drafts,
    )?;
    Ok(PreparedPostExecutionDriveV2 {
        scheduled,
        query,
        submission_effect,
        direct,
        lifecycle,
        terminal_projection_condition_ids,
        evidence,
        recovery_operation: DurableRecoveryOperationV2::DriveExecutionThrough {
            effective_processing_at_utc_ms: actual_cutoff_utc_ms,
        },
        disposition: SubmissionDriveDispositionV1::ItemProcessed { request_completed },
    })
}

fn prepare_query_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    pending_requests: &BTreeMap<String, PendingDomainRequestV1>,
    query_state: &'a mut QueryStateV1,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let action = session
        .first_pending_action_through(requested_cutoff_utc_ms)
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "查询执行准备缺少到期逻辑动作",
        ))?;
    match pending_requests.get(&action.global_request_id) {
        Some(PendingDomainRequestV1::Order(_)) => prepare_order_execution_drive_fields_v2(
            session,
            pending_requests,
            query_state,
            direct_response_outbox,
            lifecycle_outbox,
            requested_cutoff_utc_ms,
            occupied_lifecycle_capacity_leases,
        ),
        Some(PendingDomainRequestV1::Orders(_) | PendingDomainRequestV1::Trades(_)) => {
            prepare_list_query_execution_drive_fields_v2(
                session,
                pending_requests,
                query_state,
                direct_response_outbox,
                lifecycle_outbox,
                requested_cutoff_utc_ms,
                occupied_lifecycle_capacity_leases,
            )
        }
        Some(_) => Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非查询请求进入查询执行准备",
        )),
        None => Err(SubmissionProcessingErrorV1::InternalInvariant(
            "查询执行准备缺少领域请求",
        )),
    }
}

fn prepare_order_execution_drive_v2<'a>(
    execution_session: &'a mut SimExecutionSessionV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let SimExecutionSessionV1 {
        session,
        pending_requests,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        ..
    } = execution_session;
    prepare_order_execution_drive_fields_v2(
        session,
        pending_requests,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        requested_cutoff_utc_ms,
        occupied_lifecycle_capacity_leases,
    )
}

fn prepare_order_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    pending_requests: &BTreeMap<String, PendingDomainRequestV1>,
    query_state: &'a mut QueryStateV1,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let rule_snapshot_sha256 = session.rule_snapshot().file_sha256().clone();
    let scenario_sha256 = session.scenario().scenario_sha256().clone();
    let fee_rule = fee_rule_identity(session);
    let prefix = prepare_execution_drive_prefix_v2(session, requested_cutoff_utc_ms, false)
        .map_err(submission_processing_error_from_market_event_v2)?;
    let action = prefix
        .current_action()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "Order 执行准备缺少到期逻辑动作",
        ))?;
    let request = pending_requests
        .get(&action.global_request_id)
        .cloned()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "Order 执行准备缺少领域请求",
        ))?;
    validate_action_mapping(&request, &action)?;
    let PendingDomainRequestV1::Order(order_request) = &request else {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非 Order 请求进入 Order 执行准备",
        ));
    };

    let lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let mut materialized = materialize_execution_drive_prefix_v2(
        prefix,
        query_state,
        lifecycle,
        Some(&action.global_request_id),
        occupied_lifecycle_capacity_leases,
    )
    .map_err(submission_processing_error_from_market_event_v2)?;

    let query_sha256 = canonical_request_sha256(&request);
    materialized.scheduled.prepare_query_revision(
        &action.global_request_id,
        &action.action_identity,
        query_sha256,
    )?;
    let hot_order = match materialized
        .scheduled
        .execution_candidate()
        .candidate_order(&order_request.platform_order_id)
    {
        Some(order) if materialized.query.hot_order_is_query_visible(order)? => Some(order),
        Some(_) | None => None,
    };
    let result = match hot_order {
        Some(order) => OrderQueryResultV1::Found(Box::new(project_order(order)?)),
        None => match materialized
            .query
            .retained_terminal_order(&order_request.platform_order_id)
        {
            Some(order) => OrderQueryResultV1::Found(Box::new(order.clone())),
            None => match materialized.query.order_history_retained_from_utc_ms() {
                Some(retained_from_utc_ms) => {
                    OrderQueryResultV1::OutOfRetention(QueryOutOfRetentionV1 {
                        scope: QueryRetentionScopeV1::OrderHistory,
                        retained_from_utc_ms: Some(retained_from_utc_ms),
                        requested_root_sequence: None,
                        earliest_retained_root_sequence: materialized
                            .query
                            .earliest_retained_root_sequence(),
                    })
                }
                None => OrderQueryResultV1::NotFound,
            },
        },
    };
    let part = DirectResponsePartV1::Order {
        effective_processing_at_utc_ms: action.key.effective_processing_at_utc_ms,
        result,
    };
    finish_materialized_query_action_v2(
        materialized,
        direct_response_outbox,
        action,
        request,
        part,
        rule_snapshot_sha256,
        scenario_sha256,
        fee_rule,
    )
}

fn prepare_list_query_execution_drive_v2<'a>(
    execution_session: &'a mut SimExecutionSessionV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let SimExecutionSessionV1 {
        session,
        pending_requests,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        ..
    } = execution_session;
    prepare_list_query_execution_drive_fields_v2(
        session,
        pending_requests,
        query_state,
        direct_response_outbox,
        lifecycle_outbox,
        requested_cutoff_utc_ms,
        occupied_lifecycle_capacity_leases,
    )
}

fn prepare_list_query_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    pending_requests: &BTreeMap<String, PendingDomainRequestV1>,
    query_state: &'a mut QueryStateV1,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let session_spec = session.session_spec().clone();
    let rule_snapshot_sha256 = session.rule_snapshot().file_sha256().clone();
    let scenario_sha256 = session.scenario().scenario_sha256().clone();
    let fee_rule = fee_rule_identity(session);
    let prefix = prepare_execution_drive_prefix_v2(session, requested_cutoff_utc_ms, false)
        .map_err(submission_processing_error_from_market_event_v2)?;
    let action = prefix
        .current_action()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "列表查询执行准备缺少到期逻辑动作",
        ))?;
    let request = pending_requests
        .get(&action.global_request_id)
        .cloned()
        .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
            "列表查询执行准备缺少领域请求",
        ))?;
    validate_action_mapping(&request, &action)?;
    if !matches!(
        &request,
        PendingDomainRequestV1::Orders(_) | PendingDomainRequestV1::Trades(_)
    ) {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "非列表查询请求进入列表查询执行准备",
        ));
    }

    let lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let mut materialized = materialize_execution_drive_prefix_v2(
        prefix,
        query_state,
        lifecycle,
        Some(&action.global_request_id),
        occupied_lifecycle_capacity_leases,
    )
    .map_err(submission_processing_error_from_market_event_v2)?;
    let query_sha256 = canonical_request_sha256(&request);
    let effective_processing_at_utc_ms = action.key.effective_processing_at_utc_ms;

    let part = match &request {
        PendingDomainRequestV1::Orders(request) => {
            let result = if request.cursor.is_some() {
                let frozen_revision = materialized.query.continuation_query_projection_revision(
                    &action.global_request_id,
                    ListQueryMethodV1::Orders,
                )?;
                materialized.scheduled.prepare_query_revision_at(
                    &action.global_request_id,
                    &action.action_identity,
                    query_sha256,
                    frozen_revision,
                )?;
                materialized
                    .query
                    .prepare_continue_orders(&action.global_request_id)?
            } else {
                let revision = materialized.scheduled.prepare_query_revision(
                    &action.global_request_id,
                    &action.action_identity,
                    query_sha256,
                )?;
                let mut rows = materialized
                    .scheduled
                    .execution_candidate()
                    .candidate_orders()
                    .map(|order| {
                        let active = order
                            .pending_maker_depletion_base_units
                            .checked_add(order.open_base_units)
                            .ok_or(MatchingMathErrorV1::ArithmeticOverflow)?;
                        if active == 0
                            || !request
                                .filter
                                .condition_id
                                .as_ref()
                                .is_none_or(|id| id.0 == order.condition_id)
                            || !request
                                .filter
                                .token_id
                                .as_ref()
                                .is_none_or(|id| id.0 == order.token_id)
                        {
                            return Ok(None);
                        }
                        project_order(order).map(Some)
                    })
                    .collect::<Result<Vec<_>, MatchingMathErrorV1>>()?
                    .into_iter()
                    .flatten()
                    .collect::<Vec<_>>();
                rows.sort_by(|left, right| {
                    (left.created_at_utc_ms, left.platform_order_id.as_str())
                        .cmp(&(right.created_at_utc_ms, right.platform_order_id.as_str()))
                });
                OrdersQueryResultV1::Page(materialized.query.prepare_new_orders_page(
                    &session_spec,
                    orders_filter_sha256(&request.filter),
                    revision.platform_state_revision,
                    rows,
                )?)
            };
            DirectResponsePartV1::Orders {
                effective_processing_at_utc_ms,
                result,
            }
        }
        PendingDomainRequestV1::Trades(request) => {
            let result = if request.cursor.is_some() {
                let frozen_revision = materialized.query.continuation_query_projection_revision(
                    &action.global_request_id,
                    ListQueryMethodV1::Trades,
                )?;
                materialized.scheduled.prepare_query_revision_at(
                    &action.global_request_id,
                    &action.action_identity,
                    query_sha256,
                    frozen_revision,
                )?;
                materialized
                    .query
                    .prepare_continue_trades(&action.global_request_id)?
            } else {
                let revision = materialized.scheduled.prepare_query_revision(
                    &action.global_request_id,
                    &action.action_identity,
                    query_sha256,
                )?;
                let normalized_interval = strict_millisecond_interval(&request.filter);
                let empty_interval = normalized_interval.is_none();
                let retained_exact_trade = request.filter.trade_id.as_ref().is_some_and(|id| {
                    materialized
                        .scheduled
                        .execution_candidate()
                        .candidate_fill(id)
                        .is_some_and(|fill| {
                            materialized.query.trade_is_retained(fill.matched_at_utc_ms)
                        })
                        || materialized.query.retained_terminal_trade(id).is_some()
                });
                if !empty_interval
                    && !retained_exact_trade
                    && materialized
                        .query
                        .trade_history_retained_from_utc_ms()
                        .is_some_and(|floor| {
                            normalized_interval
                                .is_some_and(|(first_inclusive, _)| first_inclusive < floor)
                        })
                {
                    TradesQueryResultV1::OutOfRetention(QueryOutOfRetentionV1 {
                        scope: QueryRetentionScopeV1::TradeHistory,
                        retained_from_utc_ms: materialized
                            .query
                            .trade_history_retained_from_utc_ms(),
                        requested_root_sequence: None,
                        earliest_retained_root_sequence: materialized
                            .query
                            .earliest_retained_root_sequence(),
                    })
                } else {
                    let mut rows_by_id = BTreeMap::new();
                    if !empty_interval {
                        if let Some(trade_id) = &request.filter.trade_id {
                            if let Some(fill) = materialized
                                .scheduled
                                .execution_candidate()
                                .candidate_fill(trade_id)
                                .filter(|fill| {
                                    materialized.query.trade_is_retained(fill.matched_at_utc_ms)
                                        && fill_matches_trades_filter(fill, &request.filter)
                                })
                            {
                                let projection = project_trade(fill)?;
                                rows_by_id
                                    .insert(projection.simulated_trade_id.clone(), projection);
                            }
                        } else {
                            for fill in materialized
                                .scheduled
                                .execution_candidate()
                                .candidate_fills()
                                .filter(|fill| {
                                    materialized.query.trade_is_retained(fill.matched_at_utc_ms)
                                        && fill_matches_trades_filter(fill, &request.filter)
                                })
                            {
                                let projection = project_trade(fill)?;
                                rows_by_id
                                    .insert(projection.simulated_trade_id.clone(), projection);
                            }
                        }
                        if let Some(trade_id) = &request.filter.trade_id {
                            if let Some(trade) = materialized
                                .query
                                .retained_terminal_trade(trade_id)
                                .filter(|trade| {
                                    trade_projection_matches_trades_filter(trade, &request.filter)
                                })
                            {
                                rows_by_id
                                    .entry(trade.simulated_trade_id.clone())
                                    .or_insert_with(|| trade.clone());
                            }
                        } else {
                            for trade in
                                materialized
                                    .query
                                    .retained_terminal_trades()
                                    .filter(|trade| {
                                        trade_projection_matches_trades_filter(
                                            trade,
                                            &request.filter,
                                        )
                                    })
                            {
                                rows_by_id
                                    .entry(trade.simulated_trade_id.clone())
                                    .or_insert_with(|| trade.clone());
                            }
                        }
                    }
                    let mut rows = rows_by_id.into_values().collect::<Vec<_>>();
                    rows.sort_by(|left, right| {
                        (left.matched_at_utc_ms, left.simulated_trade_id.as_str())
                            .cmp(&(right.matched_at_utc_ms, right.simulated_trade_id.as_str()))
                    });
                    TradesQueryResultV1::Page(materialized.query.prepare_new_trades_page(
                        &session_spec,
                        trades_filter_sha256(&request.filter),
                        revision.platform_state_revision,
                        rows,
                    )?)
                }
            };
            DirectResponsePartV1::Trades {
                effective_processing_at_utc_ms,
                result,
            }
        }
        _ => unreachable!("列表查询方法已经在准备前验证"),
    };

    finish_materialized_query_action_v2(
        materialized,
        direct_response_outbox,
        action,
        request,
        part,
        rule_snapshot_sha256,
        scenario_sha256,
        fee_rule,
    )
}

fn finish_materialized_query_action_v2<'a>(
    materialized: MaterializedExecutionDrivePrefixV2<'a>,
    direct_response_outbox: &'a mut LogicalDirectResponseOutboxV1,
    action: QueuedLogicalActionV1,
    request: PendingDomainRequestV1,
    part: DirectResponsePartV1,
    rule_snapshot_sha256: Sha256Hex,
    scenario_sha256: Sha256Hex,
    fee_rule: SubmissionFeeRuleIdentityV1,
) -> Result<PreparedQueryExecutionDriveV2<'a>, SubmissionProcessingErrorV1> {
    let MaterializedExecutionDrivePrefixV2 {
        session_id,
        mut scheduled,
        query,
        lifecycle,
        terminal_projection_condition_ids,
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        after_query_projection_revision,
        actual_cutoff_utc_ms,
        mut new_private_output_drafts,
        scheduled_state_changed: _,
    } = materialized;
    let query_revision = scheduled.query_revision_for_request(&action.global_request_id);
    let logical_action_result = durable_logical_action_result(
        &action.global_request_id,
        &request,
        usize::from(action.key.batch_item_ordinal),
        query_revision,
        &part,
    )
    .map_err(|error| SessionError::Durability(error.to_string()))?;

    let mut direct = direct_response_outbox.prepare_entry_delta_v2(&action.global_request_id)?;
    direct.record_part(part)?;
    scheduled.finish_current_action(&action.action_identity)?;
    if !scheduled.request_completed() {
        return Err(SubmissionProcessingErrorV1::InternalInvariant(
            "单项查询请求完成动作后仍未完成",
        ));
    }
    let platform_responded_at_utc_ms =
        direct
            .platform_responded_at()
            .ok_or(SubmissionProcessingErrorV1::InternalInvariant(
                "查询直接响应缺少平台响应时点",
            ))?;
    let private_emission_sequence = scheduled.next_private_emission_sequence()?;
    let transit = scheduled.prepare_complete_direct_response(
        &action.global_request_id,
        platform_responded_at_utc_ms,
        private_emission_sequence,
    )?;
    if let Some(draft) = direct.complete_draft(
        request.context().clone(),
        &transit,
        rule_snapshot_sha256,
        scenario_sha256,
        fee_rule,
    )? {
        new_private_output_drafts.push(draft);
    }

    let evidence = logical_transaction_evidence_from_after_values_v2(
        DurableTransactionFactV1::ExecutionAdvanced { session_id },
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        after_query_projection_revision,
        Some(actual_cutoff_utc_ms),
        before_private_schedule_through_utc_ms,
        vec![logical_action_result],
        new_private_output_drafts,
    )?;
    Ok(PreparedQueryExecutionDriveV2 {
        scheduled,
        query,
        direct,
        lifecycle,
        terminal_projection_condition_ids,
        evidence,
        recovery_operation: DurableRecoveryOperationV2::DriveExecutionThrough {
            effective_processing_at_utc_ms: actual_cutoff_utc_ms,
        },
        disposition: SubmissionDriveDispositionV1::ItemProcessed {
            request_completed: true,
        },
    })
}

fn prepare_scheduled_execution_drive_v2<'a>(
    session: &'a mut SimExecutionSessionV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedScheduledExecutionDriveV2<'a>, MarketEventErrorV1> {
    let SimExecutionSessionV1 {
        session,
        query_state,
        lifecycle_outbox,
        ..
    } = session;
    prepare_scheduled_execution_drive_fields_v2(
        session,
        query_state,
        lifecycle_outbox,
        requested_cutoff_utc_ms,
        occupied_lifecycle_capacity_leases,
    )
}

fn prepare_scheduled_execution_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    query_state: &'a mut QueryStateV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    requested_cutoff_utc_ms: i64,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedScheduledExecutionDriveV2<'a>, MarketEventErrorV1> {
    let prefix = prepare_execution_drive_prefix_v2(session, requested_cutoff_utc_ms, false)?;
    if prefix.current_action().is_some() {
        return Ok(PreparedScheduledExecutionDriveV2::ActionDue(prefix));
    }
    let lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let materialized = materialize_execution_drive_prefix_v2(
        prefix,
        query_state,
        lifecycle,
        None,
        occupied_lifecycle_capacity_leases,
    )?;
    finish_no_action_scheduled_execution_drive_v2(materialized)
}

fn scheduled_lifecycle_feedbacks_v2(
    execution: &crate::matching::PreparedExecutionDriveDeltaV2<'_>,
) -> Result<Vec<((i64, u8, u64), ScheduledLifecycleFeedbackV1)>, MarketEventErrorV1> {
    let mut stable_ordinal = 0_u64;
    let mut lifecycle_feedbacks = Vec::new();
    for effect in execution.gtd_expiration_effects() {
        if let Some(account_delta) = effect.account_delta.clone() {
            lifecycle_feedbacks.push((
                (
                    account_delta.platform_effective_at_utc_ms,
                    0_u8,
                    stable_ordinal,
                ),
                ScheduledLifecycleFeedbackV1::Order(OrderLifecycleFeedbackSeedV1 {
                    platform_order_id: effect.platform_order_id.clone(),
                    condition_id: effect.condition_id.clone(),
                    token_id: effect.token_id.clone(),
                    event_kind: OrderLifecycleEventKindV1::GtdExpired,
                    order_status: simulated_order_status("EXPIRED"),
                    venue_dust_closed_base_units: 0,
                    venue_dust_released_quote_units: 0,
                    market_resolved_canceled_base_units: 0,
                    market_resolved_released_quote_units: 0,
                    account_delta,
                }),
            ));
            stable_ordinal = stable_ordinal
                .checked_add(1)
                .ok_or(SessionError::ResponseDeliveryIdentityConflict)?;
        }
    }
    for lifecycle in execution.scheduled_finality_effects() {
        lifecycle_feedbacks.push((
            (
                lifecycle.trade_feedback.platform_event_at_utc_ms,
                1_u8,
                stable_ordinal,
            ),
            ScheduledLifecycleFeedbackV1::Trade(lifecycle.trade_feedback.clone()),
        ));
        stable_ordinal = stable_ordinal
            .checked_add(1)
            .ok_or(SessionError::ResponseDeliveryIdentityConflict)?;
        for effect in &lifecycle.settlement_feedbacks {
            let feedback = settlement_lifecycle_feedback_seed(effect.clone())?;
            lifecycle_feedbacks.push((
                (feedback.platform_event_at_utc_ms, 1_u8, stable_ordinal),
                ScheduledLifecycleFeedbackV1::Settlement(feedback),
            ));
            stable_ordinal = stable_ordinal
                .checked_add(1)
                .ok_or(SessionError::ResponseDeliveryIdentityConflict)?;
        }
    }
    for effect in execution.rebate_clock_effects() {
        let feedback = settlement_lifecycle_feedback_seed(effect.clone())?;
        lifecycle_feedbacks.push((
            (feedback.platform_event_at_utc_ms, 2_u8, stable_ordinal),
            ScheduledLifecycleFeedbackV1::Settlement(feedback),
        ));
        stable_ordinal = stable_ordinal
            .checked_add(1)
            .ok_or(SessionError::ResponseDeliveryIdentityConflict)?;
    }
    lifecycle_feedbacks.sort_by_key(|(key, _)| *key);
    Ok(lifecycle_feedbacks)
}

fn prepare_executing_closed_bucket_drive_fields_v2<'a>(
    session: &'a mut SimSession,
    query_state: &'a mut QueryStateV1,
    lifecycle_outbox: &'a mut LogicalLifecycleOutboxV1,
    bucket: &ClosedMarketEventBucketV1,
    occupied_lifecycle_capacity_leases: usize,
) -> Result<PreparedExecutingClosedBucketDriveAttemptV2<'a>, MarketEventErrorV1> {
    let session_id = session.session_spec().session_id.clone();
    let account_instance_key = session.execution_state().account_instance_key().clone();
    let before_query_projection_revision = session.platform_state_revision();
    let before_logical_platform_through_utc_ms = session.logical_platform_driven_through();
    let before_private_schedule_through_utc_ms = session.private_fact_schedule_closed_through();
    let bucket_reference = bucket.durable_reference();
    let bucket_work_identity = bucket.lifecycle_work_identity();
    let prepared = session.prepare_executing_closed_bucket_session_drive_v2(bucket)?;
    let crate::session::PreparedClosedBucketSessionDriveAttemptV2::Applied(mut session) = prepared
    else {
        let crate::session::PreparedClosedBucketSessionDriveAttemptV2::FailedInputSeal(outcome) =
            prepared
        else {
            unreachable!("闭桶会话准备结果形状固定")
        };
        return Ok(PreparedExecutingClosedBucketDriveAttemptV2::FailedInputSeal(outcome));
    };

    let actual_cutoff_utc_ms = session.actual_cutoff_utc_ms();
    let first_due_at_utc_ms = session.first_due_at_utc_ms();
    let query_projection_changed = session.execution_candidate().query_projection_changed();
    let terminal_projection_condition_ids = session.terminal_projection_condition_ids().clone();
    let scheduled_feedbacks = scheduled_lifecycle_feedbacks_v2(session.execution_candidate())?;
    let ordered_dpt_effects = session.dpt_effects().ordered_lifecycle_effects.clone();
    let after_query_projection_revision = if query_projection_changed {
        session.advance_platform_state_revision_once()?
    } else {
        before_query_projection_revision
    };

    let mut query = query_state.prepare_delta_v2();
    if !terminal_projection_condition_ids.is_empty() {
        let orders = session
            .execution_candidate()
            .candidate_orders()
            .filter(|order| terminal_projection_condition_ids.contains(&order.condition_id))
            .map(project_order)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| MarketEventErrorV1::ExecutionState(format!("{error:?}")))?;
        let trades = session
            .execution_candidate()
            .candidate_fills()
            .filter(|fill| terminal_projection_condition_ids.contains(&fill.condition_id))
            .map(project_trade)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| MarketEventErrorV1::ExecutionState(format!("{error:?}")))?;
        query.prepare_terminal_inserts(orders, trades)?;
    }

    let mut lifecycle = lifecycle_outbox.prepare_lifecycle_delta_v2();
    let mut new_private_output_drafts = Vec::new();
    if !scheduled_feedbacks.is_empty() {
        let latest_feedback_at_utc_ms = scheduled_feedbacks
            .iter()
            .map(|(_, feedback)| feedback.platform_effective_at_utc_ms())
            .max()
            .expect("非空生命周期反馈必须包含最晚时点");
        let reservation = lifecycle.reserve_platform_work(
            &format!(
                "SCHEDULED:{}:{latest_feedback_at_utc_ms}:{actual_cutoff_utc_ms}",
                first_due_at_utc_ms.expect("生命周期反馈必须来自已排定平台工作")
            ),
            None,
            latest_feedback_at_utc_ms,
            occupied_lifecycle_capacity_leases,
        )?;
        for (_, feedback) in scheduled_feedbacks {
            new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                &session_id,
                &account_instance_key,
                &mut session,
                &mut lifecycle,
                &reservation,
                feedback,
            )?);
        }
        lifecycle.complete_platform_work(&reservation)?;
    }

    if !ordered_dpt_effects.is_empty() {
        let reservation = lifecycle.reserve_platform_work(
            &format!("DPT:{bucket_work_identity}"),
            None,
            actual_cutoff_utc_ms,
            occupied_lifecycle_capacity_leases,
        )?;
        for effect in ordered_dpt_effects {
            match effect {
                AuthorizedMarketLifecycleEffectV2::TradeFinality(effect) => {
                    new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                        &session_id,
                        &account_instance_key,
                        &mut session,
                        &mut lifecycle,
                        &reservation,
                        ScheduledLifecycleFeedbackV1::Trade(effect.trade_feedback),
                    )?);
                    for settlement in effect.settlement_feedbacks {
                        new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                            &session_id,
                            &account_instance_key,
                            &mut session,
                            &mut lifecycle,
                            &reservation,
                            ScheduledLifecycleFeedbackV1::Settlement(
                                settlement_lifecycle_feedback_seed(settlement)?,
                            ),
                        )?);
                    }
                }
                AuthorizedMarketLifecycleEffectV2::VenueDust(effect) => {
                    new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                        &session_id,
                        &account_instance_key,
                        &mut session,
                        &mut lifecycle,
                        &reservation,
                        ScheduledLifecycleFeedbackV1::Order(OrderLifecycleFeedbackSeedV1 {
                            platform_order_id: effect.platform_order_id,
                            condition_id: effect.condition_id,
                            token_id: effect.token_id,
                            event_kind: OrderLifecycleEventKindV1::VenueDustTerminal,
                            order_status: simulated_order_status("VENUE_DUST_TERMINAL"),
                            venue_dust_closed_base_units: effect.closed_base_units,
                            venue_dust_released_quote_units: effect.released_open_quote_units,
                            market_resolved_canceled_base_units: 0,
                            market_resolved_released_quote_units: 0,
                            account_delta: effect.account_delta,
                        }),
                    )?);
                }
                AuthorizedMarketLifecycleEffectV2::MarketResolutionOrder(effect) => {
                    new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                        &session_id,
                        &account_instance_key,
                        &mut session,
                        &mut lifecycle,
                        &reservation,
                        ScheduledLifecycleFeedbackV1::Order(OrderLifecycleFeedbackSeedV1 {
                            platform_order_id: effect.platform_order_id,
                            condition_id: effect.condition_id,
                            token_id: effect.token_id,
                            event_kind: OrderLifecycleEventKindV1::MarketResolvedCanceled,
                            order_status: simulated_order_status(
                                "ORDER_STATUS_CANCELED_MARKET_RESOLVED",
                            ),
                            venue_dust_closed_base_units: 0,
                            venue_dust_released_quote_units: 0,
                            market_resolved_canceled_base_units: effect.canceled_base_units,
                            market_resolved_released_quote_units: effect.released_open_quote_units,
                            account_delta: effect.account_delta,
                        }),
                    )?);
                }
                AuthorizedMarketLifecycleEffectV2::Settlement(effect) => {
                    new_private_output_drafts.extend(record_prepared_lifecycle_feedback_v2(
                        &session_id,
                        &account_instance_key,
                        &mut session,
                        &mut lifecycle,
                        &reservation,
                        ScheduledLifecycleFeedbackV1::Settlement(
                            settlement_lifecycle_feedback_seed(effect)?,
                        ),
                    )?);
                }
            }
        }
        lifecycle.complete_platform_work(&reservation)?;
    }

    let evidence = logical_transaction_evidence_from_after_values_v2(
        DurableTransactionFactV1::PlatformBucketApplied {
            session_id: session_id.clone(),
            bucket: bucket_reference,
        },
        before_query_projection_revision,
        before_logical_platform_through_utc_ms,
        before_private_schedule_through_utc_ms,
        after_query_projection_revision,
        Some(actual_cutoff_utc_ms),
        before_private_schedule_through_utc_ms,
        Vec::new(),
        new_private_output_drafts,
    )?;
    Ok(PreparedExecutingClosedBucketDriveAttemptV2::Applied(
        PreparedExecutingClosedBucketDriveV2 {
            session,
            query,
            lifecycle,
            terminal_projection_condition_ids,
            evidence,
            recovery_operation: DurableRecoveryOperationV2::ApplyClosedMarketEventBucket,
        },
    ))
}

